'use strict';
const ENGINE_TYPES={ram:{name:'Taran',wood:60,stone:10,gold:20,seconds:12,hp:40,range:1.6,damage:8,interval:2.2},catapult:{name:'Katapulta',wood:100,stone:35,gold:40,seconds:18,hp:28,range:6,damage:12,interval:3}};
const UPGRADE_TYPES={sword:{name:'Miecze',hint:'+0,5 obrażeń piechoty i +1 siły wyprawy / poziom',wood:10,stone:20,gold:30},bow:{name:'Łuki',hint:'+0,5 obrażeń łuczników i +1 siły wyprawy / poziom',wood:10,stone:20,gold:30},armor:{name:'Zbroje',hint:'Mniejsze obrażenia żołnierzy i straty wypraw',wood:5,stone:30,gold:35}};
function initStrategy(){const w=state.war;w.engines??=[];w.engineQueue??=[];w.upgrades??={sword:0,bow:0,armor:0};w.support??=[];w.nextUnitId??=1;w.strategyClock??=0;for(const k of Object.keys(UPGRADE_TYPES))w.upgrades[k]??=0;syncGarrisonActors();ensureUnitIds()}
function ensureUnitIds(){for(const u of [...state.war.guards,...state.war.engines])u.uid??='unit-'+state.war.nextUnitId++}
function upgradeLevel(key){return state.war.upgrades?.[key]||0}
function soldierDamage(u){return (u.kind==='crossbow'?4:u.kind==='shield'?1.6:u.kind==='cavalry'?3:2)+.5*upgradeLevel(isRangedUnit(u)?'bow':'sword')+(typeof frontierSoldierBonus==='function'?frontierSoldierBonus(u):0)}
function armorDamage(amount){return amount/(1+.25*upgradeLevel('armor'))}
function armyStrength(count,army){return Array.from({length:count},(_,i)=>army?.[i]).reduce((n,u)=>n+(u?.kind==='cavalry'?6:4)+upgradeLevel(isRangedUnit(u)?'bow':'sword'),0)+(typeof frontierArmyBonus==='function'?frontierArmyBonus(count,army):0)}
function strategyDefensePower(){const w=state.war,o=villageOrigin(),patrols=(w.patrols||[]).flatMap(p=>p.units).filter(u=>Math.hypot(u.x/T-o.x,u.y/T-o.y)<9),allies=w.support.filter(a=>a.phase==='defend').flatMap(a=>a.units).filter(u=>Math.hypot(u.x/T-o.x,u.y/T-o.y)<9);const localGuards=w.guards.filter(u=>Math.hypot(u.x/T-o.x,u.y/T-o.y)<9);return armyStrength(localGuards.length,localGuards)+armyStrength(patrols.length,patrols)+allies.length*4+(typeof castleLevel==='function'?castleLevel()*10:0)+ownCount('wieza')*10+Math.min(20,ownCount('palisada')*.4)}
function strategyLoseDefenders(count){const w=state.war,o=villageOrigin(),near=u=>Math.hypot(u.x/T-o.x,u.y/T-o.y)<9;for(let i=w.guards.length-1;i>=0&&count>0;i--)if(near(w.guards[i])){w.guards.splice(i,1);w.soldiers--;count--}for(const p of w.patrols)for(let i=p.units.length-1;i>=0&&count>0;i--)if(near(p.units[i])){p.units.splice(i,1);count--}w.patrols=w.patrols.filter(p=>p.units.length)}
function buyUpgrade(key){const d=UPGRADE_TYPES[key];if(!Object.hasOwn(UPGRADE_TYPES,key))return false;if(!ownCount('kuznia')){say('Najpierw zbuduj kuźnię.');return false}const n=upgradeLevel(key)+1;if(n>3){say('To ulepszenie ma już najwyższy poziom.');return false}if(state.wood<d.wood*n||state.stone<d.stone*n||state.gold<d.gold*n){say('Brakuje surowców na ulepszenie.');return false}state.wood-=d.wood*n;state.stone-=d.stone*n;state.gold-=d.gold*n;state.war.upgrades[key]=n;warLog(d.name+': poziom '+n+'. Ulepszenie obejmuje także istniejących żołnierzy.');ui();save();renderStrategyPanel();return true}
function recruitEngine(kind){if(!Object.hasOwn(ENGINE_TYPES,kind))return false;const d=ENGINE_TYPES[kind],w=state.war;if(!state.settled||!ownCount('warsztat')){say('Najpierw zbuduj warsztat oblężniczy.');return false}if(w.engines.length+w.engineQueue.length>=ownCount('warsztat')*4){say('Warsztat daje 4 miejsca na machiny.');return false}if(state.wood<d.wood||state.stone<d.stone||state.gold<d.gold){say('Brakuje surowców na machinę.');return false}state.wood-=d.wood;state.stone-=d.stone;state.gold-=d.gold;w.engineQueue.push({kind,remaining:d.seconds});warLog(d.name+' w budowie ('+d.seconds+' s).');save();ui();renderStrategyPanel();return true}
let selectedUnits=new Set(),commandDraft=null,strategyTab='army',strategySignature='';
function selectableUnits(){return [...state.war.guards,...state.war.engines]}
function selectedActors(){return selectableUnits().filter(u=>selectedUnits.has(u.uid))}
function selectArmy(kind='soldiers'){if(typeof cancelNavalOrder==='function')cancelNavalOrder();syncGarrisonActors();ensureUnitIds();cancelPatrolDraft();setMode(null);commandDraft=null;selectedUnits=new Set((kind==='engines'?state.war.engines:state.war.guards).slice(0,10).map(u=>u.uid));showCommandBar();renderStrategyPanel();if(!selectedUnits.size)say('Brak dostępnych jednostek tego rodzaju.');return selectedUnits.size}
function armCommand(kind){if(typeof cancelNavalOrder==='function')cancelNavalOrder();if(!['move','attack','repair'].includes(kind))return false;if(kind!=='repair'&&!selectedActors().length){say('Najpierw zaznacz żołnierza albo machinę.');return false}cancelPatrolDraft();setMode(null);commandDraft=kind;$('strategyPanel').classList.add('hidden');$('warPanel').classList.add('hidden');showCommandBar();say(kind==='move'?'Kliknij odkryte miejsce docelowe.':kind==='attack'?'Kliknij wrogi oddział lub budowlę osady, z którą masz wojnę.':'Kliknij uszkodzoną budowlę lub ruiny w pobliżu ludka.');return true}
function clearCommands(){for(const u of selectedActors()){delete u.order;u.path=[];u.home={x:Math.floor(u.x/T),y:Math.floor(u.y/T)}}commandDraft=null;showCommandBar();save();say('Oddział zatrzymany. Nadal broni się przed wrogiem.');renderStrategyPanel()}
function cancelCommand(){commandDraft=null;selectedUnits.clear();showCommandBar();renderStrategyPanel()}
function showCommandBar(){const n=selectedActors().length;$('commandBar').style.display=commandDraft==='repair'?'none':n||commandDraft?'flex':'none';$('commandStatus').textContent=commandDraft==='repair'?'Naprawa: wskaż budowlę':commandDraft==='move'?'Ruch: wskaż miejsce':commandDraft==='attack'?'Atak: wskaż wroga':'Zaznaczono: '+n+'/10'}
function nearestApproach(u,x,y,range=1){let best=null;for(let r=0;r<=range;r++)for(let dx=-r;dx<=r;dx++)for(let dy=-r;dy<=r;dy++){const px=x+dx,py=y+dy;if(Math.hypot(dx,dy)>range||!unitWalkable(u,px,py)||foreignBuilding(px,py))continue;const d=Math.hypot((px+.5)*T-u.x,(py+.5)*T-u.y);if(!best||d<best.d)best={x:px,y:py,d}}return best}
function issueMapCommand(x,y){
 if(commandDraft==='repair')return repairBuilding(x,y);
 if(!seen.has(tileKey(x,y))){say('Najpierw odkryj ten teren.');return false}
 const actors=selectedActors();if(!actors.length)return false;let targetTown=null,targetRaid=null;
 if(commandDraft==='attack'){const f=foreignBuilding(x,y);targetTown=f&&state.towns.find(t=>t.id===f.townId&&t.relation==='war');targetRaid=state.war.raids.find(r=>{const p=routePosition(r);return Math.hypot(p.x/T-x-.5,p.y/T-y-.5)<2.5});if(!targetTown&&!targetRaid){say('Wskaż wrogi oddział albo budowlę osady podczas wojny.');return false}}
 const moveSpots=commandDraft==='move'&&typeof formationMoveSpots==='function'?formationMoveSpots(actors,x,y):[];if(commandDraft==='move'&&!moveSpots.length)for(let r=0;r<=Math.ceil(Math.sqrt(actors.length))+2&&moveSpots.length<actors.length;r++)for(let dx=-r;dx<=r;dx++)for(let dy=-r;dy<=r;dy++)if(Math.max(Math.abs(dx),Math.abs(dy))===r&&seen.has(tileKey(x+dx,y+dy))&&actors.every(u=>unitWalkable(u,x+dx,y+dy))&&!foreignBuilding(x+dx,y+dy))moveSpots.push({x:x+dx,y:y+dy});
 let assigned=0;for(const u of actors){const point=targetTown?nearestApproach(u,(typeof desertSiegeTarget==='function'?desertSiegeTarget(targetTown).x:targetTown.x),(typeof desertSiegeTarget==='function'?desertSiegeTarget(targetTown).y:targetTown.y),u.kind==='catapult'?5:isRangedUnit(u)?soldierRange(u)-1:1):targetRaid?nearestApproach(u,Math.floor(routePosition(targetRaid).x/T),Math.floor(routePosition(targetRaid).y/T),2):moveSpots[assigned];if(!point||!unitWalkable(u,point.x,point.y)||foreignBuilding(point.x,point.y))continue;const path=typeof planUnitRoute==='function'?[]:findRoute(u,point,true);if(path===null)continue;u.order={kind:commandDraft==='attack'?'attack':'move',x:point.x,y:point.y,townId:targetTown?.id,raidTownId:targetRaid?.townId};u.path=path;u.orderRetry=0;assigned++}
 if(!assigned){say('Brak drogi dla wybranych jednostek. Sprawdź bramy, drzewa i mosty.');return false}commandDraft=null;showCommandBar();warLog('Wydano rozkaz dla '+assigned+' jednostek.');save();renderStrategyPanel();return true;
}
function stepOrder(u,goal,dt,speed=96){
 if(Math.hypot((goal.x+.5)*T-u.x,(goal.y+.5)*T-u.y)<3)return true;
 u.orderRetry=Math.max(0,(u.orderRetry||0)-dt);u.path??=[];
 if(!u.path.length){if(u.orderRetry>0)return false;const path=typeof planUnitRoute==='function'?planUnitRoute(u,goal,true):findRoute(u,goal,true);if(path===undefined)return false;if(path===null){u.blocked=true;u.orderRetry=2;return false}u.path=path;u.blocked=false}
 const p=u.path[0];if(!p)return false;if(!unitWalkable(u,Math.floor(p.x/T),Math.floor(p.y/T))){u.path=[];u.blocked=true;u.orderRetry=.2;if(typeof cancelUnitRoute==='function')cancelUnitRoute(u);return false}
 const d=Math.hypot(p.x-u.x,p.y-u.y),step=speed*(typeof mountedSpeed==='function'?mountedSpeed(u):1)*pathSpeed(u.x,u.y)*dt;if(d<=step){u.x=p.x;u.y=p.y;u.path.shift()}else{u.x+=(p.x-u.x)/d*step;u.y+=(p.y-u.y)/d*step}return false;
}
function conquerWithOrders(t){if(t.relation!=='war')return;t.relation='conquered';if(typeof grantCampGems==='function')grantCampGems('town:'+t.id);t.power=0;state.gold+=30;state.war.raids=state.war.raids.filter(r=>r.townId!==t.id);for(const u of selectableUnits())if(u.order?.townId===t.id){delete u.order;u.path=[];u.home={x:Math.floor(u.x/T),y:Math.floor(u.y/T)}}warLog('Zdobyto '+t.name+'! Oddział pozostaje na miejscu. +30 monet.');save()}
function handleUnitOrder(u,dt){
 if(!u.order)return false;const o=u.order;const goalKey=o.x+','+o.y;if(u.routeGoal!==goalKey){u.routeGoal=goalKey;u.path=[];if(typeof cancelUnitRoute==='function')cancelUnitRoute(u)}
 if(o.kind==='attack'&&o.raidTownId){const r=state.war.raids.find(r=>r.townId===o.raidTownId&&r.power>0);if(!r){delete u.order;u.path=[];return false}if(defendActor(u,dt))return true;const p=routePosition(r);const goal=nearestApproach(u,Math.floor(p.x/T),Math.floor(p.y/T),2);if(goal){o.x=goal.x;o.y=goal.y;stepOrder(u,o,dt)}return true}
 if(o.kind==='attack'&&o.townId){const t=state.towns.find(t=>t.id===o.townId);if(t?.relation!=='war'){delete u.order;u.path=[];return false}const range=isRangedUnit(u)?soldierRange(u):1.8,d=Math.hypot(u.x/T-t.x-.5,u.y/T-t.y-.5);if(d<=range){u.fighting=true;u.healing=false;u.restTime=0;u.attackCooldown=Math.max(0,(u.attackCooldown||0)-dt);if(u.attackCooldown<=0){u.attackCooldown=u.kind==='crossbow'?2.2:1;t.power=Math.max(0,t.power-soldierDamage(u));if(typeof recordHeroHit==='function')recordHeroHit(u);u.hp=Math.max(0,(u.hp??8)-armorDamage(.6,u));u.attackUntil=state.time+.3;if(isRangedUnit(u))u.shot={x:u.x,y:u.y-16,tx:(t.x+.5)*T,ty:(t.y+.5)*T-16,time:state.time};if(t.power<=0)conquerWithOrders(t);save()}return true}}
 // Move orders take priority over chasing enemies; units resume defence at their destination.
 u.fighting=false;healDefender(u,dt);if(stepOrder(u,o,dt)){u.home={x:o.x,y:o.y};if(o.kind==='move'){delete u.order;save()}}return true;
}
function buildingMaxHp(b){const type=b.type==='ruiny'?b.originalType:b.type;if(type==='start')return 150+(b.castleLevel||0)*100;return ['palisada','brama','brama_swoi'].includes(type)?60:type==='wieza'?120:type==='start'?150:90}
function damageBuilding(b,damage){if(!b||b.type==='ruiny'||b.type==='sciezka'||b.type==='wawoz')return false;b.hp=Math.max(0,(b.hp??buildingMaxHp(b))-damage);b.lastDamage=state.time;if(b.hp<=0){b.originalType=b.type;b.type='ruiny';warLog('Zniszczono: '+(defs.find(d=>d[0]===b.originalType)?.[2]||'budowlę')+'. Możesz odbudować ruiny.');refreshWater()}save();return true}
function repairCost(b){const d=defs.find(d=>d[0]===(b.originalType||b.type)),fraction=b.type==='ruiny'?.5:((buildingMaxHp(b)-(b.hp??buildingMaxHp(b)))/buildingMaxHp(b))*.3;return {wood:Math.max(2,Math.ceil((d?.[3]||10)*fraction)),stone:Math.max(1,Math.ceil((d?.[4]||4)*fraction))}}
function repairBuilding(x,y){const b=building(x,y);if(!b||(b.type!=='ruiny'&&(b.hp??buildingMaxHp(b))>=buildingMaxHp(b))){say('Ta budowla nie potrzebuje naprawy.');return false}if(Math.hypot(x+.5-state.p.x/T,y+.5-state.p.y/T)>8){say('Podejdź do budowli na odległość 8 pól.');return false}if(state.war.raids.some(r=>{const p=routePosition(r);return r.power>0&&Math.hypot(p.x/T-x,p.y/T-y)<5})){say('Najpierw odeprzyj wroga w pobliżu budowli.');return false}const cost=repairCost(b);if(state.wood<cost.wood||state.stone<cost.stone){say('Naprawa wymaga '+cost.wood+' drewna i '+cost.stone+' kamienia.');return false}state.wood-=cost.wood;state.stone-=cost.stone;if(b.type==='ruiny'){b.type=b.originalType;delete b.originalType;if(['brama','brama_swoi'].includes(b.type))b.open=false}b.hp=buildingMaxHp(b);warLog('Naprawiono budowlę: '+cost.wood+' drewna, '+cost.stone+' kamienia.');save();ui();renderStrategyPanel();return true}
function offerAlliance(id){if(state.campaign?.stage==='desert'){say('Z orkami nie można zawrzeć sojuszu.');return false}const t=state.towns.find(t=>t.id===id);if(!state.settled||!t?.discovered||t.relation!=='neutral'){say('Sojusz można zawrzeć z odkrytą osadą w pokoju.');return false}if(state.gold<50||state.food<30){say('Poselstwo wymaga 50 monet i 30 żywności.');return false}state.gold-=50;state.food-=30;t.relation='allied';t.aidCooldown=0;warLog('Sojusz z '+t.name+'! Sojusznicy przyślą pomoc podczas najazdu.');save();ui();renderStrategyPanel();return true}
function breakAlliance(id){const t=state.towns.find(t=>t.id===id);if(t?.relation!=='allied')return false;t.relation='neutral';t.truce=120;state.war.support=state.war.support.filter(a=>a.townId!==id);warLog('Zakończono sojusz z '+t.name+'. Rozejm: 2 minuty.');save();ui();renderStrategyPanel();return true}
function damageForeignTown(t,damage){if(t.relation!=='war')return;t.fortHp??=90;t.fortHp=Math.max(0,t.fortHp-damage);if(!t.fortHp&&!t.fortBroken){t.fortBroken=true;t.power=Math.max(1,Math.ceil(t.power*.5));warLog('Machina zburzyła umocnienia '+t.name+'! Siła obrony spadła o połowę.')}else if(t.fortBroken){t.power=Math.max(0,t.power-damage*.25);if(!t.power)conquerWithOrders(t)}save()}
function updateEngine(u,dt){
 const d=ENGINE_TYPES[u.kind];u.hp??=d.hp;u.cooldown=Math.max(0,(u.cooldown||0)-dt);u.fighting=false;
 let t=u.order?.townId&&state.towns.find(t=>t.id===u.order.townId&&t.relation==='war');
 if(u.order?.townId&&!t){delete u.order;u.path=[]}
 const raid=state.war.raids.filter(r=>r.power>0&&(!u.order?.raidTownId||r.townId===u.order.raidTownId)).map(r=>({r,p:routePosition(r)})).sort((a,b)=>Math.hypot(a.p.x-u.x,a.p.y-u.y)-Math.hypot(b.p.x-u.x,b.p.y-u.y))[0];
 const siegePoint=t&&(typeof desertSiegeTarget==='function'?desertSiegeTarget(t):t);const target=t?{x:(siegePoint.x+.5)*T,y:(siegePoint.y+.5)*T}:raid?.p,distance=target?Math.hypot(target.x-u.x,target.y-u.y)/T:Infinity;
 if(u.order?.kind!=='move'&&target&&distance<=d.range&&(u.kind==='catapult'||(t&&typeof orcGateClosed==='function'&&orcGateClosed(t)?battleClearLine(u,{x:target.x+(u.x-target.x)/Math.max(1,distance*T)*T*.55,y:target.y+(u.y-target.y)/Math.max(1,distance*T)*T*.55}):battleClearLine(u,target)))){u.fighting=true;if(u.cooldown<=0){u.cooldown=d.interval;u.shot={x:u.x,y:u.y-10,tx:target.x,ty:target.y-15,time:state.time};if(t)damageForeignTown(t,d.damage);else{raid.r.power=Math.max(0,raid.r.power-(u.kind==='catapult'?5:4));raid.r.lastHit=state.time} }if(raid&&distance<1.5)u.hp=Math.max(0,u.hp-dt*1.5);return}
 if(u.order){if(u.order.raidTownId){const r=state.war.raids.find(r=>r.townId===u.order.raidTownId&&r.power>0);if(!r){delete u.order;return}const p=routePosition(r),goal=nearestApproach(u,Math.floor(p.x/T),Math.floor(p.y/T),2);if(goal){u.order.x=goal.x;u.order.y=goal.y}}
 if(stepOrder(u,u.order,dt,52)&&u.order.kind==='move'){delete u.order;save()}}
}
function updateEnemyEngines(dt){for(const r of state.war.raids){if(r.power<=0)continue;r.engine??={kind:r.siege?'ram':'catapult',cooldown:2};const p=routePosition(r),d=ENGINE_TYPES[r.engine.kind];r.engine.cooldown=Math.max(0,r.engine.cooldown-dt);const targets=state.buildings.filter(b=>!['ruiny','sciezka','wawoz'].includes(b.type)&&Math.hypot((b.x+.5)*T-p.x,(b.y+.5)*T-p.y)<=d.range*T).sort((a,b)=>Math.hypot(a.x+.5-p.x/T,a.y+.5-p.y/T)-Math.hypot(b.x+.5-p.x/T,b.y+.5-p.y/T));if(targets.length&&r.engine.cooldown<=0){const b=targets[0];r.engine.cooldown=d.interval;r.engine.shot={x:p.x,y:p.y-12,tx:(b.x+.5)*T,ty:(b.y+.5)*T,time:state.time};damageBuilding(b,d.damage);if(b.type==='ruiny'&&r.siege){r.siegeRetry=0}}}}
function updateSupport(dt){const w=state.war;for(const t of state.towns)t.aidCooldown=Math.max(0,(t.aidCooldown||0)-dt);if(w.raids.some(r=>r.power>0)){const o=villageOrigin();for(const t of state.towns.filter(t=>t.relation==='allied'&&!t.aidCooldown&&!w.support.some(a=>a.townId===t.id)).sort((a,b)=>Math.hypot(a.x-o.x,a.y-o.y)-Math.hypot(b.x-o.x,b.y-o.y)).slice(0,Math.max(0,3-w.support.length))){const route=campaignRoute(t,o,true);if(!route){t.aidCooldown=15;continue;}w.support.push({townId:t.id,route,progress:0,naval:true,troops:3,phase:'march',units:[],rest:0});t.aidCooldown=180;warLog(t.name+' wysyła 3 sojuszniczych żołnierzy!');save()}}
 for(const a of w.support){if(!state.towns.some(t=>t.id===a.townId&&t.relation==='allied')){a.done=true;continue}if(a.phase==='march'){advanceCampaign(a,dt,3.2);if(a.progress>=a.route.length-1){const o=villageOrigin();a.phase='defend';a.units=Array.from({length:3},(_,i)=>{const p=nearbySpot(o.x-1+i,o.y-1)||o;return {x:(p.x+.5)*T,y:(p.y+.5)*T,hp:8,kind:'melee',path:[],home:p}});warLog('Sojusznicza pomoc dotarła do wioski.');save()}}else{for(const u of a.units){if(!defendActor(u,dt))healDefender(u,dt)}a.units=a.units.filter(u=>u.hp>0);a.troops=a.units.length;if(!a.troops)a.done=true;if(!w.raids.some(r=>r.power>0)){a.rest+=dt;if(a.rest>10){a.done=true;warLog('Sojusznicy wracają do swojej osady.');save()}}else a.rest=0}}w.support=w.support.filter(a=>!a.done)}
function updateStrategy(dt){
 const w=state.war;ensureUnitIds();updateSupport(dt);updateEnemyEngines(dt);
 if(w.engineQueue.length&&ownCount('warsztat')){w.engineQueue[0].remaining-=dt;if(w.engineQueue[0].remaining<=0){const q=w.engineQueue.shift(),office=state.buildings.find(b=>b.type==='warsztat'),p=nearbySpot(office.x,office.y+1)||villageOrigin();w.engines.push({uid:'unit-'+w.nextUnitId++,kind:q.kind,hp:ENGINE_TYPES[q.kind].hp,x:(p.x+.5)*T,y:(p.y+.5)*T,path:[]});warLog(ENGINE_TYPES[q.kind].name+' gotowy. Zaznacz machinę i wydaj rozkaz.');save()}}
 for(const u of w.engines)updateEngine(u,dt);const lost=w.engines.filter(u=>u.hp<=0);if(lost.length){w.engines=w.engines.filter(u=>u.hp>0);warLog('Stracono machinę oblężniczą.');save()}
 for(const u of selectableUnits())for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++){const x=Math.floor(u.x/T)+dx,y=Math.floor(u.y/T)+dy;if(x>=0&&y>=0&&x<N&&y<N)seen.add(tileKey(x,y))}
 w.strategyClock+=dt;if(w.strategyClock>1){w.strategyClock=0;showCommandBar();renderStrategyPanel()}
}
function drawSiegeEngine(u,hostile=false){const x=u.x,y=u.y,wood=hostile?'#9b6551':'#aa8551';ctx.fillStyle='#1b302c55';ctx.beginPath();ctx.ellipse(x,y+8,19,7,0,0,7);ctx.fill();ctx.fillStyle='#413d30';for(const dx of [-15,10]){ctx.beginPath();ctx.arc(x+dx,y+3,6,0,7);ctx.fill()}ctx.fillStyle=wood;ctx.fillRect(x-20,y-9,40,11);ctx.strokeStyle=wood;ctx.lineWidth=5;ctx.beginPath();if(u.kind==='catapult'){ctx.moveTo(x-9,y-5);ctx.lineTo(x,y-28);ctx.lineTo(x+10,y-5);ctx.moveTo(x-8,y-26);ctx.lineTo(x+15,y-40)}else{ctx.moveTo(x-15,y-9);ctx.lineTo(x-15,y-24);ctx.moveTo(x+15,y-9);ctx.lineTo(x+15,y-24)}ctx.stroke();ctx.lineWidth=1;if(u.kind==='ram'){polygon([[x-24,y-25],[x,y-40],[x+24,y-25]],hostile?'#8d5444':'#596c48');ctx.fillStyle='#b5a16b';ctx.fillRect(x-21,y-21,42,8);ctx.fillStyle='#9ba6a1';ctx.fillRect(x+15,y-23,8,12)}else{ctx.fillStyle='#777d70';ctx.beginPath();ctx.arc(x+16,y-42,6,0,7);ctx.fill()}if(u.hp!==undefined){const max=ENGINE_TYPES[u.kind].hp;if(u.hp<max){ctx.fillStyle='#65483a';ctx.fillRect(x-19,y-49,38,4);ctx.fillStyle='#bdd98c';ctx.fillRect(x-19,y-49,38*u.hp/max,4)}}drawSiegeShot(u.shot)}
function drawSiegeShot(s){if(!s||state.time-s.time>.7)return;const f=Math.max(0,Math.min(1,(state.time-s.time)/.7)),x=s.x+(s.tx-s.x)*f,y=s.y+(s.ty-s.y)*f-Math.sin(f*Math.PI)*45;ctx.fillStyle='#d8c29b';ctx.beginPath();ctx.arc(x,y,4,0,7);ctx.fill()}
function drawStrategyStructure(b,x,y){if(b.type==='ruiny'){polygon([[x-23,y+10],[x-17,y-9],[x-2,y-2],[x+9,y-17],[x+22,y+10]],'#777666');ctx.strokeStyle='#66503b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x-14,y+5);ctx.lineTo(x+14,y-12);ctx.moveTo(x-11,y-16);ctx.lineTo(x+15,y+8);ctx.stroke();ctx.lineWidth=1;return true}if(!['kuznia','warsztat'].includes(b.type))return false;ctx.fillStyle='#8e8b77';ctx.fillRect(x-22,y-22,44,35);polygon([[x-27,y-23],[x,y-48],[x+27,y-23]],b.type==='kuznia'?'#69504a':'#6f7653');ctx.fillStyle='#4e493b';ctx.fillRect(x-7,y-4,14,17);ctx.fillStyle='#dca55c';ctx.fillRect(x-17,y-15,8,9);if(b.type==='kuznia'){ctx.fillStyle='#5f6259';ctx.fillRect(x+10,y-47,8,26);ctx.fillStyle='#ffa457';ctx.fillRect(x-4,y,8,10)}ctx.fillStyle='#f2dd9c';ctx.font='17px serif';ctx.fillText(b.type==='kuznia'?'⚒':'⚙',x-8,y-26);return true}
function drawStrategyWorld(){const visible=(x,y)=>seen.has(tileKey(Math.floor(x/T),Math.floor(y/T)));for(const u of state.war.engines)if(visible(u.x,u.y)){drawSiegeEngine(u);ctx.fillStyle='#efdaa4';ctx.font='9px system-ui';ctx.fillText(ENGINE_TYPES[u.kind].name,u.x-18,u.y-55)}
 for(const r of state.war.raids)if(r.engine){const p=routePosition(r);if(visible(p.x,p.y))drawSiegeEngine({...r.engine,x:p.x-32,y:p.y+35},true)}
 for(const a of state.war.support){if(a.phase==='march')drawCampaignForce(a,a.troops,visible);else for(const u of a.units)if(visible(u.x,u.y)){drawBattleActor(u,'#8dba84');ctx.fillStyle='#b7dfaa';ctx.font='9px system-ui';ctx.fillText('SOJUSZNIK',u.x-24,u.y-50)}}
 for(const u of selectedActors())if(visible(u.x,u.y)){const displayY=typeof unitDisplayY==='function'?unitDisplayY(u):u.y;ctx.strokeStyle='#f8dc7b';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(u.x,displayY+8,18,8,0,0,7);ctx.stroke();ctx.lineWidth=1;if(u.order){ctx.strokeStyle='#f8dc7b77';ctx.beginPath();ctx.moveTo(u.x,displayY);ctx.lineTo((u.order.x+.5)*T,(u.order.y+.5)*T);ctx.stroke()}}
 for(const b of state.buildings)if(b.hp!==undefined&&(b.hp<buildingMaxHp(b)||b.type==='ruiny')&&visible((b.x+.5)*T,(b.y+.5)*T)){const x=(b.x+.5)*T,y=(b.y+.5)*T;ctx.fillStyle='#51382d';ctx.fillRect(x-21,y-53,42,5);ctx.fillStyle=b.hp?'#e1a36e':'#a4a195';ctx.fillRect(x-21,y-53,42*b.hp/buildingMaxHp(b),5);ctx.fillStyle='#efc990';ctx.font='9px system-ui';ctx.fillText(b.type==='ruiny'?'RUINY':Math.ceil(b.hp)+'/'+buildingMaxHp(b),x-20,y-58)}
}
function strategyTabs(){return `${typeof openKingdom==='function'?'<button class="recruit kingdom-link" data-strategy="kingdom">♛ Królestwo · zamek · flota · karawany</button>':''}<div class="strategy-tabs">${[['army','Wojsko'],['forge','Kuźnia'],['allies','Sojusze'],['repair','Naprawy']].map(([key,label])=>`<button data-strategy="tab" data-value="${key}" class="${strategyTab===key?'active':''}">${label}</button>`).join('')}</div>`}
function strategyArmyUI(){const w=state.war;return `<p class="war-hint">Kliknij żołnierza lub przeciągnij ramkę na mapie. Shift dodaje i usuwa pojedyncze postacie. Grupa może liczyć od 1 do 10 jednostek. Potem wybierz Idź lub Atakuj i kliknij cel. Zaznaczeni: ${selectedActors().length}.</p><div class="war-actions"><button data-strategy="select" data-value="soldiers">Zaznacz do 10 (${w.soldiers})</button><button data-strategy="select" data-value="engines">Zaznacz machiny (${w.engines.length})</button><button data-strategy="command" data-value="move">Idź</button><button data-strategy="command" data-value="attack">Atakuj</button><button data-strategy="stop">Zatrzymaj</button></div><p class="war-hint">Ruch ma pierwszeństwo przed pościgiem. Po dojściu oddział broni wybranego miejsca. Możesz atakować budowle osad, z którymi prowadzisz wojnę, i nadchodzące najazdy.</p><h3>Machiny oblężnicze</h3><p class="war-hint">Warsztat: 4 miejsca. Taran rozbija budowle z bliska; katapulta strzela na 6 pól. Wrogowie też używają machin i mogą niszczyć Twoje budynki.</p>${Object.entries(ENGINE_TYPES).map(([k,d])=>`<button class="recruit" data-strategy="engine" data-value="${k}" ${!ownCount('warsztat')||w.engines.length+w.engineQueue.length>=ownCount('warsztat')*4?'disabled':''}>Buduj ${k==='ram'?'taran':'katapultę'} · ${d.wood} 🪵 ${d.stone} ◆ ${d.gold} ●</button>`).join('')}<p class="war-hint">${w.engineQueue.length?(ownCount('warsztat')?'Budowa: ':'Wstrzymano — odbuduj warsztat: ')+ENGINE_TYPES[w.engineQueue[0].kind].name+' · '+Math.ceil(w.engineQueue[0].remaining)+' s · kolejka '+w.engineQueue.length:'Taran: 12 s · katapulta: 18 s. Machiny nie zajmują miejsc żołnierzy.'}</p>${w.engines.map(u=>`<div class="patrol-row"><span>${ENGINE_TYPES[u.kind].name} · ${Math.ceil(u.hp)} PŻ · ${u.blocked?'brak przejścia':u.order?'wykonuje rozkaz':'gotowy'}</span><button data-strategy="unit" data-value="${u.uid}">Zaznacz</button></div>`).join('')}`}
function strategyForgeUI(){return `<p class="war-hint">Zbuduj kuźnię: 80 drewna i 35 kamienia. Każde ulepszenie ma 3 poziomy i działa na obecnych oraz nowych żołnierzy.</p>${Object.entries(UPGRADE_TYPES).map(([k,d])=>{const level=upgradeLevel(k),n=level+1;return `<section class="town-card"><b>${d.name} · poziom ${level}/3</b><p>${d.hint}</p><button data-strategy="upgrade" data-value="${k}" ${!ownCount('kuznia')||level>=3?'disabled':''}>${level>=3?'Maksymalny poziom':'Ulepsz · '+d.wood*n+' 🪵 '+d.stone*n+' ◆ '+d.gold*n+' ●'}</button></section>`}).join('')}`}
function strategyAlliesUI(){const allies=state.towns.filter(t=>t.relation==='allied');return `<p class="war-hint">Sojusze: ${allies.length}. Poselstwo kosztuje 50 monet i 30 żywności. Podczas najazdu maksymalnie 3 najbliższych sojuszników przyśle po 3 żołnierzy. Muszą dotrzeć drogą; ponowna pomoc po 3 minutach. Sojusznicy nie wypowiadają Ci wojny.</p>${state.war.support.map(a=>`<p class="war-notice">Pomoc: ${state.towns.find(t=>t.id===a.townId)?.name} · ${a.troops} żołnierzy · ${a.phase==='march'?'w drodze':'broni wioski'}</p>`).join('')}${state.towns.filter(t=>t.discovered&&['neutral','allied'].includes(t.relation)).map(t=>`<section class="town-card"><b>${t.name} · ${t.relation==='allied'?'Sojusz':'Pokój'}</b><div class="war-actions"><button data-strategy="${t.relation==='allied'?'break':'alliance'}" data-value="${t.id}">${t.relation==='allied'?'Zakończ sojusz':'Zawrzyj sojusz · 50 ● 30 🌾'}</button><button data-strategy="locate" data-value="${t.id}">Wskaż osadę</button></div></section>`).join('')||'<p class="war-hint">Odkryj pokojową osadę, aby zawrzeć sojusz.</p>'}`}
function strategyRepairUI(){const damaged=state.buildings.filter(b=>b.type==='ruiny'||(b.hp??buildingMaxHp(b))<buildingMaxHp(b));return `<p class="war-hint">Uszkodzone budowle i ruiny: ${damaged.length}. Podejdź na 8 pól. Naprawa działa po odparciu wroga w promieniu 5 pól. Odbudowa kosztuje połowę ceny budowy; naprawa zależy od uszkodzeń.</p><button class="recruit" data-strategy="command" data-value="repair">Napraw — wskaż budowlę na mapie</button>${damaged.map(b=>{const cost=repairCost(b);return `<section class="town-card"><b>${defs.find(d=>d[0]===(b.originalType||b.type))?.[2]||'Domek'} · ${b.x}, ${b.y}</b><p>${b.type==='ruiny'?'Ruiny':Math.ceil(b.hp)+'/'+buildingMaxHp(b)+' PŻ'} · ${cost.wood} 🪵 ${cost.stone} ◆</p><button data-strategy="repair" data-x="${b.x}" data-y="${b.y}">${b.type==='ruiny'?'Odbuduj':'Napraw'}</button></section>`}).join('')}`}
function renderStrategyPanel(){if($('strategyPanel').classList.contains('hidden'))return;const w=state.war,signature=JSON.stringify([strategyTab,[...selectedUnits],Math.floor(state.wood),Math.floor(state.stone),Math.floor(state.food),state.gold,w.upgrades,w.engines.map(u=>[u.uid,u.kind,Math.ceil(u.hp),u.order?.kind,u.blocked]),w.engineQueue.map(q=>[q.kind,Math.ceil(q.remaining)]),w.soldiers,ownCount('warsztat'),ownCount('kuznia'),state.towns.map(t=>[t.id,t.relation,t.discovered]),w.support.map(a=>[a.townId,a.phase,a.troops]),state.buildings.filter(b=>b.hp!==undefined).map(b=>[b.x,b.y,b.type,Math.ceil(b.hp)])]);if(signature===strategySignature)return;strategySignature=signature;$('strategyContent').innerHTML=strategyTabs()+({army:strategyArmyUI,forge:strategyForgeUI,allies:strategyAlliesUI,repair:strategyRepairUI}[strategyTab])()}
function openStrategy(tab='army'){if(typeof openKingdom==='function')$('kingdomPanel').classList.add('hidden');strategyTab=tab;strategySignature='';$('warPanel').classList.add('hidden');$('strategyPanel').classList.remove('hidden');renderStrategyPanel()}
$('strategyOpen').onclick=()=>openStrategy();$('strategyClose').onclick=()=>$('strategyPanel').classList.add('hidden');
$('strategyPanel').onclick=e=>{const b=e.target.closest('button[data-strategy]');if(!b||b.disabled)return;const v=b.dataset.value;switch(b.dataset.strategy){case 'kingdom':openKingdom();break;case 'tab':strategyTab=v;break;case 'select':selectArmy(v);break;case 'unit':selectedUnits=new Set([v]);showCommandBar();break;case 'command':armCommand(v);break;case 'stop':clearCommands();break;case 'engine':recruitEngine(v);break;case 'upgrade':buyUpgrade(v);break;case 'alliance':offerAlliance(v);break;case 'break':breakAlliance(v);break;case 'locate':state.war.waypoint=v;save();ui();break;case 'repair':repairBuilding(Number(b.dataset.x),Number(b.dataset.y));break}renderStrategyPanel()};
$('commandMove').onclick=()=>armCommand('move');$('commandAttack').onclick=()=>armCommand('attack');$('commandStop').onclick=clearCommands;$('commandCancel').onclick=cancelCommand;
window.addEventListener('keydown',e=>{if(e.key==='Escape')cancelCommand()});
const clickBeforeStrategy=c.onpointerdown;c.onpointerdown=e=>{const p=worldPoint(e);if(!mode&&commandDraft){issueMapCommand(Math.floor(p.x/T),Math.floor(p.y/T));return}if(!mode&&!patrolDraft){syncGarrisonActors();ensureUnitIds();const u=selectableUnits().filter(u=>Math.hypot(u.x-p.x,(typeof unitDisplayY==='function'?unitDisplayY(u):u.y)-14-p.y)<22).sort((a,b)=>Math.hypot(a.x-p.x,(typeof unitDisplayY==='function'?unitDisplayY(a):a.y)-p.y)-Math.hypot(b.x-p.x,(typeof unitDisplayY==='function'?unitDisplayY(b):b.y)-p.y))[0];if(u){if(typeof toggleUnitSelection==='function')toggleUnitSelection(u,!!e.shiftKey);else{if(!e.shiftKey)selectedUnits.clear();if(selectedUnits.has(u.uid))selectedUnits.delete(u.uid);else selectedUnits.add(u.uid);showCommandBar();renderStrategyPanel();}return}}clickBeforeStrategy(e)};
initStrategy();ui();

// Returning to the axe or construction also leaves any pending map command.
const commandSetMode=setMode;setMode=function(m){commandDraft=null;commandSetMode(m);showCommandBar()};
